import {isAdmin} from '@/lib/auth';import {supabaseServer} from '@/lib/supabase/server';import AdminEditor from '@/components/AdminEditor';export default async function Page(){if(!await isAdmin())return <p>403</p>;const db=await supabaseServer();const [{data:items},{data:modules}]=await Promise.all([db.from('lessons').select('id,title,content,module_id,is_published').order('created_at',{ascending:false}),db.from('learning_modules').select('id,title')]);return <><h1>Manajemen Materi</h1><AdminEditor kind="lessons" initial={items||[]} modules={modules||[]}/></>}